using UnityEngine;
namespace LWS.TruckBowling {
public sealed class BowlingAI:MonoBehaviour {
 public BowlingLane lane;public int Decisions{get;private set;}public int Reversals{get;private set;}float targetX,entryX,entryHeading,next,steeringError,targetSpeed,stuck,reverse;Vector3 previous;
 public void Plan(){float front=float.MaxValue,total=0;int count=0;foreach(var p in lane.pins)if(p.gameObject.activeSelf&&!p.credited)front=Mathf.Min(front,p.transform.position.z);foreach(var p in lane.pins)if(p.gameObject.activeSelf&&!p.credited&&p.transform.position.z<front+1.0f){total+=p.transform.position.x;count++;}var level=lane.Owner.difficulty;float error=level==BowlingDifficulty.Easy?.34f:level==BowlingDifficulty.Normal?.07f:.03f;bool full=lane.Owner.score.RemainingPins==10;targetX=count==0?lane.center:total/count;
  if(full)targetX=lane.center+(Random.value<.5f?-1:1)*(level==BowlingDifficulty.Easy?.14f:.18f);
  else if(level!=BowlingDifficulty.Easy){float best=float.NegativeInfinity;foreach(var candidate in lane.pins){if(!candidate.gameObject.activeSelf||candidate.credited)continue;float value=0;foreach(var p in lane.pins)if(p.gameObject.activeSelf&&!p.credited&&Mathf.Abs(p.transform.position.x-candidate.transform.position.x)<.85f)value+=1/(1+Mathf.Max(0,p.transform.position.z-front)*.12f);value-=Mathf.Abs(candidate.transform.position.x-lane.center)*.06f;if(value>best){best=value;targetX=candidate.transform.position.x;}}}
  targetX+=Random.Range(-error,error);if(!full)targetX=Mathf.Clamp(targetX,lane.center-(level==BowlingDifficulty.Hard?1.45f:1.2f),lane.center+(level==BowlingDifficulty.Hard?1.45f:1.2f));entryX=Mathf.Clamp(targetX,lane.center-lane.halfWidth+.75f,lane.center+lane.halfWidth-.75f);entryHeading=Mathf.Atan2(targetX-entryX,lane.pinLine)*Mathf.Rad2Deg;steeringError=Random.Range(-error,error)*(level==BowlingDifficulty.Normal?1.3f:1.7f);targetSpeed=(level==BowlingDifficulty.Easy?12.7f:level==BowlingDifficulty.Normal?15.2f:15.7f)+Random.Range(-.4f,.2f);stuck=reverse=next=0;previous=lane.truck.body.position;}
 void FixedUpdate(){if(lane==null||!lane.Driving||!lane.match.DeliveryAllowed||lane.match.Paused||lane.Owner.source!=BowlingSource.AI)return;float dt=Time.fixedDeltaTime;var t=lane.truck;var p=t.body.position;if(!lane.Committed&&Vector3.Distance(p,previous)<.012f&&Mathf.Abs(t.throttle)>.3f)stuck+=dt;else stuck=Mathf.Max(0,stuck-dt);previous=p;
  if(stuck>2.2f&&!lane.Committed){reverse=1.0f;stuck=0;Reversals++;}if(reverse>0){reverse-=dt;t.Control(new Vector2((p.x>lane.center?-1:1)*.3f,-.6f));return;}if(Time.time<next)return;var difficulty=lane.Owner.difficulty;next=Time.time+(difficulty==BowlingDifficulty.Easy?.28f:difficulty==BowlingDifficulty.Normal?.09f:.06f);Decisions++;
  if(lane.Committed&&t.ControlLost){t.Control(Vector2.zero);return;}float distance=Mathf.Max(5,lane.pinLine-p.z);float desired=lane.Committed?Mathf.Atan2(targetX-p.x,distance)*Mathf.Rad2Deg:Mathf.Atan2(entryX-p.x,Mathf.Max(18,-p.z+24))*Mathf.Rad2Deg+entryHeading;float yaw=Mathf.DeltaAngle(0,t.body.rotation.eulerAngles.y);float headingError=Mathf.DeltaAngle(yaw,desired)+steeringError*(lane.Committed?.25f:1);float yawRate=t.body.angularVelocity.y*Mathf.Rad2Deg;float desiredRate=headingError*1.8f-yawRate*.9f;float wheelAngle=Mathf.Atan(desiredRate*Mathf.Deg2Rad*.86f/Mathf.Max(2.5f,t.Speed))*Mathf.Rad2Deg;float slick=Mathf.Pow(Mathf.Clamp01(lane.Furthest/lane.pinLine),t.handling.oilExponent);float limit=Mathf.Lerp(t.handling.approachSteer,t.handling.laneSteer,slick);float correction=lane.Committed?Mathf.Lerp(.55f,.12f,slick):.65f;float steer=Mathf.Clamp(wheelAngle/limit,-correction,correction);
  float predicted=p.x+t.body.linearVelocity.x*distance/Mathf.Max(2,t.body.linearVelocity.z);if(lane.Committed&&Mathf.Abs(predicted-targetX)<(difficulty==BowlingDifficulty.Easy?.22f:.12f)&&Mathf.Abs(yawRate)<3)steer=0;float throttle=lane.Committed?0:t.Speed<targetSpeed?(Mathf.Abs(headingError)>12?.65f:1):0;t.Control(new Vector2(steer,throttle));
 }
}
}
